1	// This file is the regression guard for deny-overrides across scope levels:
2	// once a deny policy covers the requested scope, a more specific allow on a
3	// descendant scope cannot let the request through. Existing suites pin
4	// recursive scope matching and same-scope policy conflicts separately; this
5	// suite puts the parent deny and the child allow into one real request, so a
6	// future authorization rewrite cannot mistake "more specific" for "allow
7	// wins".
8	//
9	// The guarded rules, all already implemented by Store.Decide/evaluate:
10	//
11	//   - A recursive deny on "org/a" covers the read of a resource in "org/a/b"
12	//     even when an exact allow for this subject and action sits on "org/a/b".
13	//     The answer is a denial explained as "matched deny policy", and the hit
14	//     list keeps BOTH policy identifiers, sorted ascending, at the version
15	//     actually evaluated.
16	//   - Swapping the two policies' submission order changes nothing in the
17	//     explanation: neither the verdict, the reason, the hit list nor the
18	//     used version may move.
19	//   - A non-recursive deny on "org/a" covers only its own scope; the same
20	//     child read is then allowed by the child allow alone.
21	//   - "org/ab" is not a child of "org/a": matching is by slash-separated
22	//     segments, never by string prefix, so a recursive deny on "org/a"
23	//     cannot block a read exactly allowed on "org/ab".
24	//
25	// Every request here is envelope-valid (the three organizations agree and
26	// subject, resource and action identifiers are present), so each outcome is
27	// genuinely produced by policy conflict, not by a request-shape rejection.
28	package darksafe
29	
30	import (
31		"reflect"
32		"testing"
33	)
34	
35	const (
36		// Shared fixture for the parent-deny/child-allow regression.
37		conflictOrg       = "acme"
38		conflictSubject   = "u1"
39		conflictAction    = "read"
40		childResourceID   = "doc-1"
41		childScope        = "org/a/b"
42		parentScope       = "org/a"
43		siblingScope      = "org/ab"
44		siblingResourceID = "doc-2"
45		parentDenyID      = "p-deny-parent"
46		childAllowID      = "p-allow-child"
47		siblingAllowID    = "p-allow-sibling"
48	)
49	
50	// denyPolicy builds one deny policy; allowPolicy is the shared helper in
51	// org_test.go.
52	func denyPolicy(id, subject, action, scope string, recursive bool) Policy {
53		return Policy{ID: id, Subject: subject, Action: action, Scope: scope, Effect: EffectDeny, Recursive: recursive}
54	}
55	
56	func childReadRequest() OrgRequest {
57		return request(conflictOrg, conflictSubject, childResourceID, childScope, conflictAction)
58	}
59	
60	func siblingReadRequest() OrgRequest {
61		return request(conflictOrg, conflictSubject, siblingResourceID, siblingScope, conflictAction)
62	}
63	
64	// conflictPolicies returns the recursive parent deny plus the exact child
65	// allow in the requested slice order, used to prove submission order cannot
66	// influence any part of the decision.
67	func conflictPolicies(denyFirst bool) []Policy {
68		deny := denyPolicy(parentDenyID, conflictSubject, conflictAction, parentScope, true)
69		allow := allowPolicy(childAllowID, conflictSubject, conflictAction, childScope, false)
70		if denyFirst {
71			return []Policy{deny, allow}
72		}
73		return []Policy{allow, deny}
74	}
75	
76	// wantDecisionShape pins the full four-field explanation: allowed, reason,
77	// sorted matched list and the version actually evaluated.
78	func wantDecisionShape(t *testing.T, got Decision, allowed bool, reason string, matched []string, version int, context string) {
79		t.Helper()
80		if got.Allowed != allowed {
81			t.Fatalf("%s: allowed = %v, want %v; decision = %+v", context, got.Allowed, allowed, got)
82		}
83		if got.Reason != reason {
84			t.Fatalf("%s: reason = %q, want %q; decision = %+v", context, got.Reason, reason, got)
85		}
86		if got.Version != version {
87			t.Fatalf("%s: version = %d, want %d (the published version used); decision = %+v",
88				context, got.Version, version, got)
89		}
90		if !reflect.DeepEqual(got.Matched, matched) {
91			t.Fatalf("%s: matched = %q, want %q; decision = %+v", context, got.Matched, matched, got)
92		}
93	}
94	
95	// TestRecursiveParentDenyOverridesMoreSpecificChildAllow is the central
96	// guard: a recursive deny on org/a covers org/a/b, so the exact allow on
97	// org/a/b cannot grant the child read. The denial must still carry the
98	// allow's identifier — it is evidence of the conflict, not something the
99	// final verdict erases — and the hit list is sorted by identifier.
100	func TestRecursiveParentDenyOverridesMoreSpecificChildAllow(t *testing.T) {
101		s := NewStore()
102		version, err := s.Publish(conflictOrg, 0, conflictPolicies(true))
103		if err != nil || version != 1 {
104			t.Fatalf("publish = %d, %v; want 1, nil", version, err)
105		}
106	
107		d := s.Decide(conflictOrg, childReadRequest())
108		wantDecisionShape(t, d,
109			false, "matched deny policy",
110			[]string{childAllowID, parentDenyID}, // ascending, both hits retained
111			version, "recursive parent deny vs exact child allow")
112	
113		// The allow hit is deliberately present on a denied decision: it is what
114		// makes the deny reason reviewable as a conflict resolution.
115		foundAllow := false
116		for _, id := range d.Matched {
117			if id == childAllowID {
118				foundAllow = true
119			}
120		}
121		if !foundAllow {
122			t.Fatalf("denial dropped the more specific allow hit %q: %+v", childAllowID, d)
123		}
124	}
125	
126	// TestConflictDecisionIsIndependentOfPolicySubmissionOrder publishes the
127	// identical two-policy conflict with the deny and allow swapped in the
128	// submitted slice. The full explanation — verdict, reason, hit list and the
129	// published version actually used — must be byte-for-byte stable.
130	func TestConflictDecisionIsIndependentOfPolicySubmissionOrder(t *testing.T) {
131		decide := func(denyFirst bool) Decision {
132			s := NewStore()
133			version, err := s.Publish(conflictOrg, 0, conflictPolicies(denyFirst))
134			if err != nil || version != 1 {
135				t.Fatalf("publish (denyFirst=%v) = %d, %v; want 1, nil", denyFirst, version, err)
136			}
137			d := s.Decide(conflictOrg, childReadRequest())
138			wantDecisionShape(t, d,
139				false, "matched deny policy",
140				[]string{childAllowID, parentDenyID}, 1,
141				"conflict decision must not depend on submission order")
142			return d
143		}
144	
145		denyFirst := decide(true)
146		allowFirst := decide(false)
147		if !reflect.DeepEqual(denyFirst, allowFirst) {
148			t.Fatalf("swapping policy submission order changed the decision:\ndeny first  = %+v\nallow first = %+v",
149				denyFirst, allowFirst)
150		}
151	}
152	
153	// TestNonRecursiveParentDenyDoesNotReachChildScope pins the Recursive flag's
154	// meaning from the other side: the same parent deny without Recursive covers
155	// org/a alone, so the child read is decided by the exact child allow and
156	// nothing else enters the hit list.
157	func TestNonRecursiveParentDenyDoesNotReachChildScope(t *testing.T) {
158		s := NewStore()
159		policies := []Policy{
160			denyPolicy(parentDenyID, conflictSubject, conflictAction, parentScope, false),
161			allowPolicy(childAllowID, conflictSubject, conflictAction, childScope, false),
162		}
163		version, err := s.Publish(conflictOrg, 0, policies)
164		if err != nil || version != 1 {
165			t.Fatalf("publish = %d, %v; want 1, nil", version, err)
166		}
167	
168		// The child read is allowed by the exact child policy alone; the parent
169		// deny is not a hit and must not appear in the explanation.
170		d := s.Decide(conflictOrg, childReadRequest())
171		wantDecisionShape(t, d,
172			true, "matched allow policy",
173			[]string{childAllowID}, version, "child read under a non-recursive parent deny")
174	
175		// The non-recursive deny still guards exactly its own scope: at org/a the
176		// child allow does not match and the deny decides, proving the child
177		// allow above came from scope semantics, not from deny being weakened.
178		atParent := s.Decide(conflictOrg, request(conflictOrg, conflictSubject, childResourceID, parentScope, conflictAction))
179		wantDecisionShape(t, atParent,
180			false, "matched deny policy",
181			[]string{parentDenyID}, version, "read at the denied scope itself")
182	}
183	
184	// TestRecursiveDenyOnOrgADoesNotCoverOrgAb guards the segment boundary:
185	// "org/ab" is a sibling prefix, not a descendant of "org/a". An exact allow
186	// on org/ab grants the org/ab read, and the recursive parent deny's
187	// identifier must never enter the hit list. No path normalization or
188	// wildcard reading is involved — matching stays slash-segment based.
189	func TestRecursiveDenyOnOrgADoesNotCoverOrgAb(t *testing.T) {
190		s := NewStore()
191		policies := []Policy{
192			denyPolicy(parentDenyID, conflictSubject, conflictAction, parentScope, true),
193			allowPolicy(siblingAllowID, conflictSubject, conflictAction, siblingScope, false),
194		}
195		version, err := s.Publish(conflictOrg, 0, policies)
196		if err != nil || version != 1 {
197			t.Fatalf("publish = %d, %v; want 1, nil", version, err)
198		}
199	
200		d := s.Decide(conflictOrg, siblingReadRequest())
201		wantDecisionShape(t, d,
202			true, "matched allow policy",
203			[]string{siblingAllowID}, version, "read at org/ab with a recursive deny on org/a")
204	
205		for _, id := range d.Matched {
206			if id == parentDenyID {
207				t.Fatalf("org/a recursive deny leaked into the org/ab hit list: %+v", d)
208			}
209		}
210	}
211	
212	// TestConflictDecisionAuditRecordKeepsAllowHit ensures the Decide call for
213	// the conflicting request leaves a complete audit record: the exact
214	// submitted request and the actual returned four-field decision — including
215	// the overridden allow hit that explains why the request was denied. The
216	// exported chain must verify, and rechecking the record must reproduce the
217	// denial from the recorded material.
218	func TestConflictDecisionAuditRecordKeepsAllowHit(t *testing.T) {
219		s := NewStore()
220		version, err := s.Publish(conflictOrg, 0, conflictPolicies(true))
221		if err != nil || version != 1 {
222			t.Fatalf("publish = %d, %v; want 1, nil", version, err)
223		}
224		req := childReadRequest()
225		d := s.Decide(conflictOrg, req)
